code.js:
$ cat vite.config.js

import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'

export default defineConfig({
  plugins: [vue()],

  // 开发服务器
  server: {
    port: 3000,                              // 自定义端口
    proxy: {
      '/api': 'http://localhost:8080'        // 代理跨域
    }
  },

  // 路径别名
  resolve: {
    alias: {
      '@': '/src'                            // @ → /src
    }
  },

  // 构建配置
  build: {
    outDir: 'dist'                           // 输出目录
  }
})

# 💡 React 项目只需把 vue() 换成 react()，其余一样！

           浏览器（localhost:5173）
              │  fetch('/api/users')
              ▼
     Vite Dev Server（代理中间件）
              │  proxy: { '/api': 'localhost:8080' }
              ▼
        后端 API（localhost:8080）
              │  返回 JSON 数据
              ▼
        浏览器 ← 收到数据（以为同源）

# 配置方法：
# vite.config.js
export default defineConfig({
  server: {
    proxy: {
      '/api': 'http://localhost:8080',
      '/ws': {
        target: 'ws://localhost:8080',
        ws: true                             // WebSocket 代理
      }
    }
  }
})

✅ 一行配置，解决跨域！
✅ Vue/React 项目中写法完全一样

# Vercel 部署（推荐）
$ npm i -g vercel
$ vercel --prod
  → 自动识别 Vite → 自动 npm run build → 部署

# Netlify 部署
$ npm run build
$ npx netlify deploy --prod --dir=dist

# GitHub Pages 部署
$ npm run build
$ npx gh-pages -d dist
  # 注意：vite.config.js 需设 base: '/repo-name/'

# Nginx 部署
server {
  listen 80;
  server_name example.com;
  root /var/www/app/dist;   # ← 指向 dist/
  index index.html;

  location / {
    try_files $uri $uri/ /index.html;  # SPA 回退
  }
}

# 子路径部署特别注意：
# vite.config.js
# export default { base: '/my-app/' }

